function isPwaAlreadyInstalled(){return(window.matchMedia&&window.matchMedia('(display-mode: standalone)').matches)||window.navigator.standalone===true}
function detectPwaInstallMethod(ua){const isIOS=/iPhone|iPad|iPod/i.test(ua)||(/Macintosh/i.test(ua)&&navigator.maxTouchPoints>1);const isAndroid=/Android/i.test(ua);const isFirefox=/Firefox|FxiOS/i.test(ua);const isMac=/Macintosh|Mac OS X/i.test(ua)&&!isIOS;const isSafari=/Safari/i.test(ua)&&!/Chrome|CriOS|Edg|OPR|SamsungBrowser|Firefox|FxiOS/i.test(ua);if(isIOS)return'ios';if(isMac&&isSafari)return'macos-safari';if(isFirefox&&isAndroid)return'android-firefox';if(isFirefox)return'desktop-firefox';return'native'}
function initPwaInstallUI(){if(isPwaAlreadyInstalled())return;const ua=navigator.userAgent;const iconPath=document.getElementById('pwa-btn-icon-path');const apkBtn=document.getElementById('apk-download-btn');const osSubtext=document.getElementById('pwa-os-subtext');const browserNameEl=document.getElementById('pwa-browser-name');const widget=document.getElementById('pwa-install-widget');if(!iconPath||!osSubtext||!browserNameEl||!widget)return;let os='macOS';if(/Android/i.test(ua)){os='Android';iconPath.setAttribute('d',PWA_OS_ICON_PATHS.android);if(apkBtn)apkBtn.classList.remove('hidden')}else if(/Win/i.test(ua)){os='Windows';iconPath.setAttribute('d',PWA_OS_ICON_PATHS.windows)}else if(/Linux/i.test(ua)){os='Linux';iconPath.setAttribute('d',PWA_OS_ICON_PATHS.linux)}else if(/iPhone|iPad|iPod/i.test(ua)){os='iOS';iconPath.setAttribute('d',PWA_OS_ICON_PATHS.apple)}else if(/Macintosh|Mac OS X/i.test(ua)){os='macOS';iconPath.setAttribute('d',PWA_OS_ICON_PATHS.apple)}osSubtext.textContent=`Download for ${os} via`;let browserName='Browser';if(/SamsungBrowser/i.test(ua))browserName='Samsung';else if(/Edg/i.test(ua))browserName='Edge';else if(/OPR|Opera/i.test(ua))browserName='Opera';else if(/FxiOS|Firefox/i.test(ua))browserName='Firefox';else if(/CriOS|Chrome/i.test(ua))browserName='Chrome';else if(/Safari/i.test(ua))browserName='Safari';browserNameEl.textContent=browserName;pwaInstallMethod=detectPwaInstallMethod(ua);if(pwaInstallMethod!=='native'){const data=PWA_INSTALL_INSTRUCTIONS[pwaInstallMethod];if(data)osSubtext.textContent=data.subtitle;widget.classList.add('pwa-widget-visible')}}
